// ── YARDIMCI FONKSİYONLAR ────────────────────────────────────────────────────
function getLevelClass(level) {
  if (level === 'Başlangıç') return 'level-start';
  if (level === 'Orta') return 'level-mid';
  return 'level-adv';
}

function openModal(type) {
  document.getElementById('modal' + (type === 'register' ? 'Register' : 'Info')).classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeModal(type) {
  document.getElementById('modal' + (type === 'register' ? 'Register' : 'Info')).classList.remove('open');
  document.body.style.overflow = '';
}
function submitForm(type) {
  const form = document.getElementById(type + 'Form');
  const success = document.getElementById(type + 'Success');
  form.style.display = 'none';
  success.style.display = 'block';
  setTimeout(() => closeModal(type), 3000);
}

// Modal dışı tıklama
document.addEventListener('click', e => {
  if (e.target.classList.contains('modal-overlay')) {
    e.target.classList.remove('open');
    document.body.style.overflow = '';
  }
});

